#include <iostream>
#include <string>
#include <memory>
#include <array>

struct Node {
    std::string name;
    std::shared_ptr<Node> next;
    explicit Node(std::string n) : name(std::move(n)), next(nullptr) {}
};

class IndexedNameList {
private:
    std::shared_ptr<Node> head;
    std::array<std::shared_ptr<Node>, 26> index{};

    static int charToIndex(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a';
        return -1;
    }

public:
    IndexedNameList() : head(nullptr) {
        index.fill(nullptr);
    }

    void insertInIndexedList(const std::string& name) {
        if (name.empty()) return;
        int idx = charToIndex(name[0]);
        if (idx < 0) return;

        auto newNode = std::make_shared<Node>(name);
        if (!head || name < head->name) {
            newNode->next = head;
            head = newNode;
        } else {
            auto curr = head;
            while (curr->next && curr->next->name < name) {
                curr = curr->next;
            }
            newNode->next = curr->next;
            curr->next = newNode;
        }
        rebuildIndex();
    }

    void rebuildIndex() {
        index.fill(nullptr);
        auto curr = head;
        while (curr) {
            int idx = charToIndex(curr->name[0]);
            if (idx >= 0 && index[idx] == nullptr) {
                index[idx] = curr;
            }
            curr = curr->next;
        }
    }

    bool searchIndexedList(const std::string& name, int& steps) const {
        steps = 0;
        if (name.empty()) return false;
        int idx = charToIndex(name[0]);
        if (idx < 0) return false;

        auto curr = index[idx];
        if (!curr) return false;

        while (curr && charToIndex(curr->name[0]) == idx) {
            ++steps;
            if (curr->name == name) return true;
            if (curr->name > name) break;
            curr = curr->next;
        }
        return false;
    }
};

int main() {
    IndexedNameList list;
    list.insertInIndexedList("Alice");
    list.insertInIndexedList("Bob");
    list.insertInIndexedList("Charlie");
    list.insertInIndexedList("David");
    list.insertInIndexedList("Delta");
    list.insertInIndexedList("Echo");
    list.insertInIndexedList("Yankee");
    list.insertInIndexedList("Zulu");

    int steps = 0;
    bool found = list.searchIndexedList("Delta", steps);
    std::cout << "Found Delta: " << (found ? "true" : "false") << " (Steps: " << steps << ")\n";

    found = list.searchIndexedList("Yankee", steps);
    std::cout << "Found Yankee: " << (found ? "true" : "false") << " (Steps: " << steps << ")\n";

    found = list.searchIndexedList("Bravo", steps);
    std::cout << "Found Bravo: " << (found ? "true" : "false") << " (Steps: " << steps << ")\n";

    return 0;
}
